import {getAudioEngine} from './audio-engine.js';
const engine=getAudioEngine(),reduce=matchMedia('(prefers-reduced-motion: reduce)');
window.labSound=(kind,options)=>engine.effect(kind,options);window.labSkiSound=state=>engine.ski(state);window.labTone=async kind=>engine.tone(kind);
window.labFeedback=correct=>{engine.effect(correct?'correct':'wrong');requestAnimationFrame(()=>document.querySelector('.explanation')?.scrollIntoView({block:'nearest',behavior:reduce.matches||document.body.classList.contains('still')?'instant':'smooth'}));if(correct)window.parkCelebrate?.();if(reduce.matches||document.body.classList.contains('still'))return;document.querySelector(correct?'.answer.correct':'.answer.wrong')?.animate([{opacity:.5,transform:'translateY(3px)'},{opacity:1,transform:'translateY(0)'}],{duration:450,easing:'cubic-bezier(.16,1,.3,1)'});};
